template.template_md:
{% block content %}
<div class="container py-5">
  <div class="bg-white border rounded-3 shadow-sm p-4 mb-4">
    <div class="d-flex flex-column flex-lg-row justify-content-between gap-3">
      <div>
        <p class="text-uppercase small text-muted mb-1">Client</p>
        <h1 class="h3 mb-0">{{ client.name }}</h1>
      </div>
      <div class="text-lg-end">
        <p class="text-muted small mb-1">Report generated</p>
        <p class="fs-5 fw-semibold mb-0">{{ report_run_timestamp.strftime('%Y-%m-%d %H:%M') if report_run_timestamp else '' }}</p>
      </div>
    </div>
    <p class="text-muted mt-3 mb-0">System inventory displaying model details, operating systems, quick specs, and upgrade indicators for the selected company.</p>
  </div>

  {% if data_sources.agents %}
  <div class="table-responsive bg-white border rounded-3 shadow-sm">
    <table class="table table-hover align-middle mb-0">
      <thead class="table-dark">
        <tr>
          <th scope="col">System Name</th>
          <th scope="col">System Model</th>
          <th scope="col">Operating System</th>
          <th scope="col">Quick Specs</th>
          <th scope="col" class="text-center">Health Indicators</th>
        </tr>
      </thead>
      <tbody>
        {% for item in data_sources.agents %}
        {% set model_value = 'N/A' %}
        {% if item.wmi_detail and item.wmi_detail.comp_sys and item.wmi_detail.comp_sys[0] and item.wmi_detail.comp_sys[0][0] and item.wmi_detail.comp_sys[0][0].Model %}
          {% set model_value = item.wmi_detail.comp_sys[0][0].Model %}
        {% endif %}
        {% set cpu_value = 'N/A' %}
        {% if item.wmi_detail and item.wmi_detail.cpu and item.wmi_detail.cpu[0] and item.wmi_detail.cpu[0][0] and item.wmi_detail.cpu[0][0].Name %}
          {% set cpu_value = item.wmi_detail.cpu[0][0].Name %}
        {% endif %}
        {% set os_value = item.operating_system if item.operating_system else 'N/A' %}
        {% set ram_value = item.total_ram ~ ' GB' if item.total_ram is not none else 'N/A' %}
        {% set ram_numeric = None %}
        {% if item.total_ram is number %}
          {% set ram_numeric = item.total_ram %}
        {% elif item.total_ram is string %}
          {% set cleaned_ram = item.total_ram|lower|replace('gb', '')|replace(' ', '') %}
          {% if cleaned_ram %}
            {% set ram_numeric = cleaned_ram|float %}
          {% endif %}
        {% endif %}
        {% set disk_capacity = namespace(values=[]) %}
        {% if item.disks %}
          {% for disk in item.disks %}
            {% if disk.total %}
              {% set _ = disk_capacity.values.append(disk.total) %}
            {% endif %}
          {% endfor %}
        {% endif %}
        {% set disk_total_display = disk_capacity.values|join(', ') if disk_capacity.values else 'N/A' %}
        {% set needs_upgrade = os_value != 'N/A' and ('windows 10' in os_value|lower) %}
        {% set needs_memory = ram_numeric is not none and ram_numeric <= 8 %}
        <tr>
          <td class="fw-semibold">{{ item.hostname if item.hostname else 'N/A' }}</td>
          <td>{{ model_value }}</td>
          <td>{{ os_value }}</td>
          <td class="spec-select">
            <select class="form-select form-select-sm">
              <option selected>Memory Total: {{ ram_value }}</option>
              <option>Hard Drive Total: {{ disk_total_display }}</option>
              <option>CPU Type: {{ cpu_value }}</option>
            </select>
          </td>
          <td class="text-center">
            <span class="badge {{ 'bg-danger' if needs_upgrade else 'bg-success' }}">Needs Upgrade: {{ 'Yes' if needs_upgrade else 'No' }}</span>
            <span class="badge {{ 'bg-danger' if needs_memory else 'bg-success' }}">Needs Memory: {{ 'Yes' if needs_memory else 'No' }}</span>
          </td>
        </tr>
        {% else %}
        <tr>
          <td colspan="5" class="text-center text-muted py-4">No systems were found for the selected client.</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
  {% else %}
  <div class="bg-white border rounded-3 shadow-sm p-5 text-center text-muted">No systems were found for the selected client.</div>
  {% endif %}
</div>
{% endblock %}
